export const getGetAiArtifactUrl = (artifactId: string,
    params: GetAiArtifactParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/ai/artifacts/${artifactId}?${stringifiedParams}` : `/api/ai/artifacts/${artifactId}`
}

